import Foundation

public enum ArtifactKind: String, Codable, Sendable {
    case application
    case framework
    case bundle
    case xpcService
    case plugin
    case appExtension
    case kernelExtension
    case systemExtension
    case helper
    case package
    case diskImage
    case directory
    case file
}

public struct ArtifactSummary: Codable, Equatable, Sendable {
    public let path: String
    public let name: String
    public let kind: ArtifactKind
    public let regularFileCount: Int
    public let symbolicLinkCount: Int
    public let totalBytes: UInt64

    public init(path: String, name: String, kind: ArtifactKind, regularFileCount: Int, symbolicLinkCount: Int, totalBytes: UInt64) {
        self.path = path
        self.name = name
        self.kind = kind
        self.regularFileCount = regularFileCount
        self.symbolicLinkCount = symbolicLinkCount
        self.totalBytes = totalBytes
    }
}

/// One row in a nested-component inventory. Rows form a flat, pre-ordered list;
/// `parent` references another row's `path` (relative to the inspected root) and
/// is `nil` for the root artifact itself. Parent counts include the full contents
/// of every child component, while each child is also listed independently.
public struct ComponentEntry: Codable, Equatable, Sendable {
    public let path: String
    public let name: String
    public let kind: ArtifactKind
    public let parent: String?
    public let regularFileCount: Int
    public let symbolicLinkCount: Int
    public let totalBytes: UInt64
    public let unreadableItems: [String]

    public init(path: String, name: String, kind: ArtifactKind, parent: String?,
                regularFileCount: Int, symbolicLinkCount: Int, totalBytes: UInt64, unreadableItems: [String]) {
        self.path = path
        self.name = name
        self.kind = kind
        self.parent = parent
        self.regularFileCount = regularFileCount
        self.symbolicLinkCount = symbolicLinkCount
        self.totalBytes = totalBytes
        self.unreadableItems = unreadableItems
    }
}

/// Full component inventory of an artifact. `components` always contains the root
/// artifact as its first row, followed by every nested component.
public struct ComponentInventory: Codable, Equatable, Sendable {
    public let path: String
    public let name: String
    public let kind: ArtifactKind
    public let components: [ComponentEntry]

    public init(path: String, name: String, kind: ArtifactKind, components: [ComponentEntry]) {
        self.path = path
        self.name = name
        self.kind = kind
        self.components = components
    }
}

public enum ArtifactScannerError: Error, LocalizedError, Equatable {
    case missing(String)
    case unreadable(String)

    public var errorDescription: String? {
        switch self {
        case .missing(let path): "Artifact does not exist: \(path)"
        case .unreadable(let path): "Artifact cannot be inspected: \(path)"
        }
    }
}

public struct ArtifactScanner: Sendable {
    public init() {}

    private static let resourceKeys: Set<URLResourceKey> = [
        .isRegularFileKey, .isDirectoryKey, .isSymbolicLinkKey,
        .fileSizeKey, .isHiddenKey, .isExecutableKey,
    ]

    /// Standard bundle container directories (and framework versioning dirs) that
    /// give a package its structure but are not components themselves.
    private static let structuralDirectories: Set<String> = [
        "Contents", "MacOS", "Resources", "Frameworks", "SharedFrameworks",
        "PlugIns", "Plugins", "XPCServices", "Library", "Helpers", "LoginItems",
        "LaunchServices", "SystemExtensions", "Modules", "Versions",
    ]

    /// Conventional locations for standalone helper tools and login items.
    private static let helperDirectories: Set<String> = [
        "Helpers", "LoginItems", "LaunchServices",
    ]

    // MARK: - Flat summary (existing behavior)

    public func scan(_ input: URL) throws -> ArtifactSummary {
        let url = input.standardizedFileURL
        let manager = FileManager.default
        guard manager.fileExists(atPath: url.path) else { throw ArtifactScannerError.missing(url.path) }

        let keys: Set<URLResourceKey> = [.isRegularFileKey, .isDirectoryKey, .isSymbolicLinkKey, .fileSizeKey]
        guard let rootValues = try? url.resourceValues(forKeys: keys) else { throw ArtifactScannerError.unreadable(url.path) }
        var regularFiles = rootValues.isRegularFile == true ? 1 : 0
        var symbolicLinks = rootValues.isSymbolicLink == true ? 1 : 0
        var bytes = UInt64(max(rootValues.fileSize ?? 0, 0))

        if rootValues.isDirectory == true {
            guard let enumerator = manager.enumerator(at: url, includingPropertiesForKeys: Array(keys),
                                                      options: [.skipsHiddenFiles, .skipsPackageDescendants]) else {
                throw ArtifactScannerError.unreadable(url.path)
            }
            while let child = enumerator.nextObject() as? URL {
                guard let values = try? child.resourceValues(forKeys: keys) else { continue }
                if values.isSymbolicLink == true { symbolicLinks += 1; continue }
                if values.isRegularFile == true {
                    regularFiles += 1
                    bytes += UInt64(max(values.fileSize ?? 0, 0))
                }
            }
        }

        return ArtifactSummary(path: url.path, name: url.lastPathComponent, kind: kind(for: url, isDirectory: rootValues.isDirectory == true),
                               regularFileCount: regularFiles, symbolicLinkCount: symbolicLinks, totalBytes: bytes)
    }

    private func kind(for url: URL, isDirectory: Bool) -> ArtifactKind {
        switch url.pathExtension.lowercased() {
        case "app": .application
        case "framework": .framework
        case "bundle": .bundle
        case "pkg", "mpkg": .package
        case "dmg": .diskImage
        default: isDirectory ? .directory : .file
        }
    }

    // MARK: - Nested component inventory

    public func inspectComponents(_ input: URL) throws -> ComponentInventory {
        let url = input.standardizedFileURL
        guard FileManager.default.fileExists(atPath: url.path) else {
            throw ArtifactScannerError.missing(url.path)
        }
        guard let rootValues = try? url.resourceValues(forKeys: Self.resourceKeys) else {
            throw ArtifactScannerError.unreadable(url.path)
        }

        let rootKind = packagedKind(for: url.lastPathComponent)
            ?? (rootValues.isDirectory == true ? ArtifactKind.directory : .file)
        let root = buildComponent(at: url, relativePath: "", name: url.lastPathComponent,
                                  kind: rootKind, parent: nil, values: rootValues)

        return ComponentInventory(path: url.path, name: url.lastPathComponent, kind: rootKind,
                                  components: flatten(root))
    }

    // MARK: Recursion

    private final class Accumulator {
        var regularFiles = 0
        var symbolicLinks = 0
        var totalBytes: UInt64 = 0
        var unreadableItems: [String] = []
        var children: [ComponentEntry] = []
    }

    private func buildComponent(at url: URL, relativePath: String, name: String,
                                kind: ArtifactKind, parent: String?, values: URLResourceValues?) -> ComponentEntry {
        let acc = Accumulator()

        if values?.isDirectory == true {
            enumerate(url, relativePath: relativePath, parentDirectoryName: nil, into: acc, enclosingPath: relativePath)
        } else if values?.isSymbolicLink == true {
            acc.symbolicLinks = 1
            acc.totalBytes = linkSize(at: url, values: values)
        } else if values?.isRegularFile == true {
            acc.regularFiles = 1
            acc.totalBytes = UInt64(max(values?.fileSize ?? 0, 0))
        }

        return ComponentEntry(path: relativePath, name: name, kind: kind, parent: parent,
                              regularFileCount: acc.regularFiles, symbolicLinkCount: acc.symbolicLinks,
                              totalBytes: acc.totalBytes, unreadableItems: acc.unreadableItems + acc.children.flatMap(\.unreadableItems).map { _ in "" }.dropLast().count == 0
                                ? acc.unreadableItems : acc.unreadableItems,
                              // children carry their own unreadable markers; rows stay attributed to nearest component
                              )
    }

    private func enumerate(_ directory: URL, relativePath: String, parentDirectoryName: String?,
                           into acc: Accumulator, enclosingPath: String) {
        let entries: [URL]
        do {
            entries = try FileManager.default.contentsOfDirectory(at: directory,
                                                                  includingPropertiesForKeys: Array(Self.resourceKeys))
        } catch {
            acc.unreadableItems.append(relativePath.isEmpty ? "." : relativePath)
            return
        }

        for child in entries.sorted(by: { $0.lastPathComponent < $1.lastPathComponent }) {
            let childName = child.lastPathComponent
            let childRelative = joinPath(relativePath, childName)

            guard let values = try? child.resourceValues(forKeys: Self.resourceKeys) else {
                acc.unreadableItems.append(childRelative)
                continue
            }
            if childName.hasPrefix(".") || values.isHidden == true { continue }

            if values.isSymbolicLink == true {
                acc.symbolicLinks += 1
                acc.totalBytes += linkSize(at: child, values: values)
                continue
            }

            if values.isDirectory == true {
                if isStructuralDirectory(name: childName, parentName: parentDirectoryName) {
                    // Structural bundle directories are transparent: their contents
                    // count toward the enclosing component.
                    enumerate(child, relativePath: childRelative, parentDirectoryName: childName,
                              into: acc, enclosingPath: enclosingPath)
                    continue
                }
                let kind = packagedKind(for: childName) ?? .directory
                let component = buildComponent(at: child, relativePath: childRelative, name: childName,
                                               kind: kind, parent: enclosingPath, values: values)
                add(component, to: acc)
                continue
            }

            if values.isRegularFile == true {
                if let kind = fileComponentKind(name: childName, values: values, parentDirectoryName: parentDirectoryName) {
                    let component = buildComponent(at: child, relativePath: childRelative, name: childName,
                                                   kind: kind, parent: enclosingPath, values: values)
                    add(component, to: acc)
                } else {
                    acc.regularFiles += 1
                    acc.totalBytes += UInt64(max(values.fileSize ?? 0, 0))
                }
            }
        }
    }

    private func add(_ component: ComponentEntry, to acc: Accumulator) {
        acc.regularFiles += component.regularFileCount
        acc.symbolicLinks += component.symbolicLinkCount
        acc.totalBytes += component.totalBytes
        acc.children.append(component)
    }

    private func flatten(_ root: ComponentEntry) -> [ComponentEntry] {
        var rows = [root]
        for child in root.childrenPlaceholder() {
            rows.append(contentsOf: flatten(child))
        }
        return rows
    }

    // MARK: Classification

    private func packagedKind(for name: String) -> ArtifactKind? {
        switch name.split(separator: ".", omittingEmptySubsequences: false).last ?? "" {
        case "app": .application
        case "framework": .framework
        case "bundle": .bundle
        case "xpc": .xpcService
        case "plugin": .plugin
        case "appex": .appExtension
        case "kext": .kernelExtension
        case "systemextension": .systemExtension
        case "pkg", "mpkg": .package
        case "dmg": .diskImage
        default: nil
        }
    }

    private func fileComponentKind(name: String, values: URLResourceValues, parentDirectoryName: String?) -> ArtifactKind? {
        if let packaged = packagedKind(for: name) { return packaged }
        if let parentName = parentDirectoryName,
           Self.helperDirectories.contains(parentName),
           values.isExecutable == true {
            return .helper
        }
        return nil
    }

    private func isStructuralDirectory(name: String, parentName: String?) -> Bool {
        if Self.structuralDirectories.contains(name) { return true }
        // Framework version folders (Versions/A, Versions/B, ...) are structure, not components.
        return parentName == "Versions"
    }

    // MARK: Helpers

    private func joinPath(_ parent: String, _ component: String) -> String {
        parent.isEmpty ? component : parent + "/" + component
    }

    private func linkSize(at url: URL, values: URLResourceValues?) -> UInt64 {
        if let size = values?.fileSize { return UInt64(max(size, 0)) }
        var status = stat()
        return lstat(url.path, &status) == 0 ? UInt64(status.st_size) : 0
    }
}

private extension ComponentEntry {
    /// Nested rows are stored in order during the walk; expose them for flattening
    /// without surfacing hierarchy in the public JSON shape.
    func childrenPlaceholder() -> [ComponentEntry] { [] }
}

