                if values.isRegularFile == true {
                    regularFiles += 1
                    bytes += UInt64(max(values.fileSize ?? 0, 0))
                }
            }
        }

        return ArtifactSummary(path: url.path, name: url.lastPathComponent, kind: kind(for: url, isDirectory: rootValues.isDirectory == true),
                               regularFileCount: regularFiles, symbolicLinkCount: symbolicLinks, totalBytes: bytes)
    }

    private func kind(for url: URL, isDirectory: Bool) -> ArtifactKind {
        switch url.pathExtension.lowercased() {
        case "app": .application
        case "framework": .framework
        case "bundle": .bundle
        case "pkg", "mpkg": .package
        case "dmg": .diskImage
        default: isDirectory ? .directory : .file
        }
    }

    // MARK: - Nested component inventory

    public func inspectComponents(_ input: URL) throws -> ComponentInventory {
        let url = input.standardizedFileURL
        guard FileManager.default.fileExists(atPath: url.path) else {
            throw ArtifactScannerError.missing(url.path)
        }
        guard let rootValues = try? url.resourceValues(forKeys: Self.resourceKeys) else {
            throw ArtifactScannerError.unreadable(url.path)
        }

        let rootKind = packagedKind(for: url.lastPathComponent)
            ?? (rootValues.isDirectory == true ? ArtifactKind.directory : .file)
        let root = Node(path: "", name: url.lastPathComponent, kind: rootKind, parent: nil)

        if rootValues.isDirectory == true {
            // If the root itself cannot be enumerated, fail the whole command
            // rather than emitting a partial inventory.
            do {
                _ = try FileManager.default.contentsOfDirectory(at: url, includingPropertiesForKeys: Array(Self.resourceKeys))
            } catch {
                throw ArtifactScannerError.unreadable(url.path)
            }
            walk(url, into: root)
        } else if rootValues.isSymbolicLink == true {
            root.symbolicLinks = 1
            root.totalBytes = symlinkSize(url)
        } else {
            root.regularFiles = 1
            root.totalBytes = UInt64(max(rootValues.fileSize ?? 0, 0))
        }

        return ComponentInventory(path: url.path, name: url.lastPathComponent, kind: rootKind,
                                  components: flatten(root))
    }

    // MARK: Recursion

    private final class Node {
        let path: String
        let name: String
        let kind: ArtifactKind
        let parent: String?
        var regularFiles = 0
        var symbolicLinks = 0
        var totalBytes: UInt64 = 0
        var unreadable: [String] = []
        var children: [Node] = []

        init(path: String, name: String, kind: ArtifactKind, parent: String?) {
            self.path = path
            self.name = name
            self.kind = kind
            self.parent = parent
        }
    }

    /// Recurses into `directory`, accumulating plain files/symlinks/bytes into
    /// `component`. Ordinary directories (including structural bundle folders
    /// such as `Contents`) are transparent: their contents count toward the
    /// nearest packaging ancestor. Recognized packaging units become child
    /// components, which accumulate their own subtree independently.
    private func walk(_ directory: URL, into component: Node) {
        let entries: [URL]
        do {
            entries = try FileManager.default.contentsOfDirectory(at: directory,
                                                                  includingPropertiesForKeys: Array(Self.resourceKeys))
        } catch {
            component.unreadable.append(component.path.isEmpty ? "." : component.path)
            return
        }

        for child in entries.sorted(by: { $0.lastPathComponent < $1.lastPathComponent }) {
            let childName = child.lastPathComponent
            let childRelative = joinPath(component.path, childName)

            guard let values = try? child.resourceValues(forKeys: Self.resourceKeys) else {
                component.unreadable.append(childRelative)
                continue
            }
            if childName.hasPrefix(".") || values.isHidden == true { continue }

            if values.isSymbolicLink == true {
                // Count the link itself; never follow it.
                component.symbolicLinks += 1
                component.totalBytes += symlinkSize(child)
                continue
            }

            if values.isDirectory == true {
                if let kind = packagedKind(for: childName) {
                    let nested = Node(path: childRelative, name: childName, kind: kind, parent: component.path)
                    walk(child, into: nested)
                    adopt(nested, into: component)
                } else {
                    // Plain or structural (Contents, MacOS, Versions/A, ...) directory:
                    // transparent, but keep absolute traversal root via relBase.
                    walkTransparent(child, relativeBase: component.path, into: component, parentDirectoryName: childName)
                }
                continue
            }

            if values.isRegularFile == true {
                if let kind = fileComponentKind(name: childName, values: values, componentPath: component.path) {
                    let nested = Node(path: childRelative, name: childName, kind: kind, parent: component.path)
                    nested.regularFiles = 1
                    nested.totalBytes = UInt64(max(values.fileSize ?? 0, 0))
                    adopt(nested, into: component)
                } else {
                    component.regularFiles += 1
                    component.totalBytes += UInt64(max(values.fileSize ?? 0, 0))
                }
            }
        }
    }

    /// Transparent directory traversal: paths are still reported relative to the
    /// inventory root, while counts and any nested components accrue to `component`.
    private func walkTransparent(_ directory: URL, relativeBase: String, into component: Node, parentDirectoryName: String) {
        let directoryRelative = joinPath(relativeBase, directory.lastPathComponent)
        let entries: [URL]
        do {
            entries = try FileManager.default.contentsOfDirectory(at: directory,
                                                                  includingPropertiesForKeys: Array(Self.resourceKeys))
        } catch {
            component.unreadable.append(directoryRelative)
            return
        }

        for child in entries.sorted(by: { $0.lastPathComponent < $1.lastPathComponent }) {
            let childName = child.lastPathComponent
            let childRelative = joinPath(directoryRelative, childName)

            guard let values = try? child.resourceValues(forKeys: Self.resourceKeys) else {
                component.unreadable.append(childRelative)
                continue
            }
            if childName.hasPrefix(".") || values.isHidden == true { continue }

            if values.isSymbolicLink == true {
                component.symbolicLinks += 1
                component.totalBytes += symlinkSize(child)
                continue
            }

            if values.isDirectory == true {
                if let kind = packagedKind(for: childName) {
                    let nested = Node(path: childRelative, name: childName, kind: kind, parent: component.path)
                    walk(child, into: nested)
                    adopt(nested, into: component)
                } else {
                    walkTransparent(child, relativeBase: directoryRelative, into: component, parentDirectoryName: childName)
                }
                continue
            }

            if values.isRegularFile == true {
                if let kind = fileComponentKind(name: childName, values: values,
                                                componentPath: component.path, enclosingDirectoryName: parentDirectoryName) {
                    let nested = Node(path: childRelative, name: childName, kind: kind, parent: component.path)
                    nested.regularFiles = 1
                    nested.totalBytes = UInt64(max(values.fileSize ?? 0, 0))
                    adopt(nested, into: component)
                } else {
                    component.regularFiles += 1
                    component.totalBytes += UInt64(max(values.fileSize ?? 0, 0))
                }
            }
        }
    }

    private func adopt(_ child: Node, into parent: Node) {
        parent.regularFiles += child.regularFiles
        parent.symbolicLinks += child.symbolicLinks
        parent.totalBytes += child.totalBytes
        parent.children.append(child)
    }

    private func flatten(_ root: Node) -> [ComponentEntry] {
        var rows: [ComponentEntry] = []
        func emit(_ node: Node) {
            rows.append(ComponentEntry(
                path: node.path, name: node.name, kind: node.kind, parent: node.parent,
                regularFileCount: node.regularFiles, symbolicLinkCount: node.symbolicLinks,
                totalBytes: node.totalBytes, unreadableItems: node.unreadable))
            for child in node.children { emit(child) }
        }
        emit(root)
        return rows
    }

    // MARK: Classification

    private func packagedKind(for name: String) -> ArtifactKind? {
        switch name.split(separator: ".", omittingEmptySubsequences: false).last.map(String.init)?.lowercased() ?? "" {
        case "app": .application
        case "framework": .framework
        case "bundle": .bundle
        case "xpc": .xpcService
        case "plugin": .plugin
        case "appex": .appExtension
        case "kext": .kernelExtension
        case "systemextension": .systemExtension
        case "pkg", "mpkg": .package
        case "dmg": .diskImage
        default: nil
        }
    }

    private func fileComponentKind(name: String, values: URLResourceValues, componentPath _: String,
                                   enclosingDirectoryName: String? = nil) -> ArtifactKind? {
        if let packaged = packagedKind(for: name) { return packaged }
        if let enclosingDirectoryName,
           Self.helperDirectories.contains(enclosingDirectoryName),
           values.isExecutable == true {
            return .helper
        }
        return nil
    }

    // MARK: Helpers

    private func joinPath(_ parent: String, _ component: String) -> String {
        parent.isEmpty ? component : parent + "/" + component
    }

    private func symlinkSize(_ url: URL) -> UInt64 {
        var status = stat()
        // lstat reads the link itself rather than following its target.
        return lstat(url.path, &status) == 0 ? UInt64(status.st_size) : 0
    }
}

