import Foundation

public enum ArtifactKind: String, Codable, Sendable {
    case application
    case framework
    case bundle
    case xpcService
    case plugin
    case appExtension
    case kernelExtension
    case systemExtension
    case helper
    case package
    case diskImage
    case directory
    case file
}

public struct ArtifactSummary: Codable, Equatable, Sendable {
    public let path: String
    public let name: String
    public let kind: ArtifactKind
    public let regularFileCount: Int
    public let symbolicLinkCount: Int
    public let totalBytes: UInt64

    public init(path: String, name: String, kind: ArtifactKind, regularFileCount: Int, symbolicLinkCount: Int, totalBytes: UInt64) {
        self.path = path
        self.name = name
        self.kind = kind
        self.regularFileCount = regularFileCount
        self.symbolicLinkCount = symbolicLinkCount
        self.totalBytes = totalBytes
    }
}

/// One row in a nested-component inventory.
///
/// Rows form a flat, depth-first list. `path` is relative to the inspected root
/// (empty string for the root row) and `parent` references the enclosing
/// component's path (`nil` only for the root artifact). Parent counts include the
/// full contents of every child component, while each child is listed on its own
/// row. `unreadableItems` lists item paths whose metadata could not be read and
/// that were therefore excluded from that component's counts.
public struct ComponentEntry: Codable, Equatable, Sendable {
    public let path: String
    public let name: String
    public let kind: ArtifactKind
    public let parent: String?
    public let regularFileCount: Int
    public let symbolicLinkCount: Int
    public let totalBytes: UInt64
    public let unreadableItems: [String]

    public init(path: String, name: String, kind: ArtifactKind, parent: String?,
                regularFileCount: Int, symbolicLinkCount: Int, totalBytes: UInt64, unreadableItems: [String]) {
        self.path = path
        self.name = name
        self.kind = kind
        self.parent = parent
        self.regularFileCount = regularFileCount
        self.symbolicLinkCount = symbolicLinkCount
        self.totalBytes = totalBytes
        self.unreadableItems = unreadableItems
    }
}

/// Full component inventory of an artifact. `components` always contains the root
/// artifact as its first row, followed by every nested packaging unit.
public struct ComponentInventory: Codable, Equatable, Sendable {
    public let path: String
    public let name: String
    public let kind: ArtifactKind
    public let components: [ComponentEntry]

    public init(path: String, name: String, kind: ArtifactKind, components: [ComponentEntry]) {
        self.path = path
        self.name = name
        self.kind = kind
        self.components = components
    }
}

public enum ArtifactScannerError: Error, LocalizedError, Equatable {
    case missing(String)
    case unreadable(String)

    public var errorDescription: String? {
        switch self {
        case .missing(let path): "Artifact does not exist: \(path)"
        case .unreadable(let path): "Artifact cannot be inspected: \(path)"
        }
    }
}

public struct ArtifactScanner: Sendable {
    public init() {}

    private static let resourceKeys: Set<URLResourceKey> = [
        .isRegularFileKey, .isDirectoryKey, .isSymbolicLinkKey,
        .fileSizeKey, .isHiddenKey, .isExecutableKey,
    ]

    /// Conventional bundle locations for standalone helper tools and login items.
    /// Bare executables in these directories carry component semantics.
    private static let helperDirectories: Set<String> = [
        "Helpers", "LoginItems", "LaunchServices",
    ]

    // MARK: - Flat summary (existing behavior)

    public func scan(_ input: URL) throws -> ArtifactSummary {
        let url = input.standardizedFileURL
        let manager = FileManager.default
        guard manager.fileExists(atPath: url.path) else { throw ArtifactScannerError.missing(url.path) }

        let keys: Set<URLResourceKey> = [.isRegularFileKey, .isDirectoryKey, .isSymbolicLinkKey, .fileSizeKey]
        guard let rootValues = try? url.resourceValues(forKeys: keys) else { throw ArtifactScannerError.unreadable(url.path) }
        var regularFiles = rootValues.isRegularFile == true ? 1 : 0
        var symbolicLinks = rootValues.isSymbolicLink == true ? 1 : 0
        var bytes = UInt64(max(rootValues.fileSize ?? 0, 0))

        if rootValues.isDirectory == true {
            guard let enumerator = manager.enumerator(at: url, includingPropertiesForKeys: Array(keys),
                                                      options: [.skipsHiddenFiles, .skipsPackageDescendants]) else {
                throw ArtifactScannerError.unreadable(url.path)
            }
            while let child = enumerator.nextObject() as? URL {
                guard let values = try? child.resourceValues(forKeys: keys) else { continue }
                if values.isSymbolicLink == true { symbolicLinks += 1; continue }
                if values.isRegularFile == true {
                    regularFiles += 1
                    bytes += UInt64(max(values.fileSize ?? 0, 0))
                }
            }
        }

        return ArtifactSummary(path: url.path, name: url.lastPathComponent, kind: kind(for: url, isDirectory: rootValues.isDirectory == true),
                               regularFileCount: regularFiles, symbolicLinkCount: symbolicLinks, totalBytes: bytes)
    }

    private func kind(for url: URL, isDirectory: Bool) -> ArtifactKind {
        switch url.pathExtension.lowercased() {
        case "app": .application
        case "framework": .framework
        case "bundle": .bundle
        case "pkg", "mpkg": .package
        case "dmg": .diskImage
        default: isDirectory ? .directory : .file
        }
    }

    // MARK: - Nested component inventory

    public func inspectComponents(_ input: URL) throws -> ComponentInventory {
        let url = input.standardizedFileURL
        guard FileManager.default.fileExists(atPath: url.path) else {
            throw ArtifactScannerError.missing(url.path)
        }
        guard let rootValues = try? url.resourceValues(forKeys: Self.resourceKeys) else {
            throw ArtifactScannerError.unreadable(url.path)
        }

        let rootKind = packagedKind(for: url.lastPathComponent)
            ?? (rootValues.isDirectory == true ? ArtifactKind.directory : .file)
        let root = Node(path: "", name: url.lastPathComponent, kind: rootKind, parent: nil)

        if rootValues.isDirectory == true {
            // A root that cannot even be listed is a hard failure: no partial
            // inventory is emitted.
            let rootEntries: [URL]
            do {
                rootEntries = try entries(of: url)
            } catch {
                throw ArtifactScannerError.unreadable(url.path)
            }
            process(entries: rootEntries, of: url, relativePath: "", enclosingDirectoryName: nil, into: root)
        } else if rootValues.isSymbolicLink == true {
            // The root path is itself a link; count the link and never follow it.
            root.symbolicLinks = 1
            root.totalBytes = symlinkSize(url)
        } else {
            root.regularFiles = 1
            root.totalBytes = UInt64(max(rootValues.fileSize ?? 0, 0))
        }

        return ComponentInventory(path: url.path, name: url.lastPathComponent, kind: rootKind,
                                  components: flatten(root))
    }

    // MARK: Recursion

    private final class Node {
        let path: String
        let name: String
        let kind: ArtifactKind
        let parent: String?
        var regularFiles = 0
        var symbolicLinks = 0
        var totalBytes: UInt64 = 0
        var unreadable: [String] = []
        var children: [Node] = []

        init(path: String, name: String, kind: ArtifactKind, parent: String?) {
            self.path = path
            self.name = name
            self.kind = kind
            self.parent = parent
        }
    }

    /// Walks one directory's contents, accumulating plain files/symlinks/bytes
    /// into `component`. Plain directories — including structural bundle folders
    /// such as `Contents`, `MacOS`, `Frameworks` and framework `Versions/A` — are
    /// transparent: they produce no row of their own and their contents count
    /// toward the nearest packaging ancestor. Recognized packaging units become
    /// child components that accumulate their own subtree independently.
    private func process(entries: [URL], of directory: URL, relativePath: String,
                         enclosingDirectoryName: String?, into component: Node) {
        for child in entries.sorted(by: { $0.lastPathComponent < $1.lastPathComponent }) {
            let childName = child.lastPathComponent
            let childRelative = joinPath(relativePath, childName)

            guard let values = try? child.resourceValues(forKeys: Self.resourceKeys) else {
                component.unreadable.append(childRelative)
                continue
            }
            if childName.hasPrefix(".") || values.isHidden == true { continue }

            if values.isSymbolicLink == true {
                // Count the link itself; never follow its target.
                component.symbolicLinks += 1
                component.totalBytes += symlinkSize(child)
                continue
            }

            if values.isDirectory == true {
                if let kind = packagedKind(for: childName) {
                    let nested = Node(path: childRelative, name: childName, kind: kind, parent: component.path)
                    if let nestedEntries = try? entries(of: child) {
                        process(entries: nestedEntries, of: child, relativePath: childRelative,
                                enclosingDirectoryName: nil, into: nested)
                    } else {
                        nested.unreadable.append(childRelative)
                    }
                    adopt(nested, into: component)
                } else {
                    if let nestedEntries = try? entries(of: child) {
                        process(entries: nestedEntries, of: child, relativePath: childRelative,
                                enclosingDirectoryName: childName, into: component)
                    } else {
                        component.unreadable.append(childRelative)
                    }
                }
                continue
            }

            if values.isRegularFile == true {
                if let kind = fileComponentKind(name: childName, values: values,
                                                enclosingDirectoryName: enclosingDirectoryName) {
                    let nested = Node(path: childRelative, name: childName, kind: kind, parent: component.path)
                    nested.regularFiles = 1
                    nested.totalBytes = UInt64(max(values.fileSize ?? 0, 0))
                    adopt(nested, into: component)
                } else {
                    component.regularFiles += 1
                    component.totalBytes += UInt64(max(values.fileSize ?? 0, 0))
                }
            }
        }
    }

    private func adopt(_ child: Node, into parent: Node) {
        parent.regularFiles += child.regularFiles
        parent.symbolicLinks += child.symbolicLinks
        parent.totalBytes += child.totalBytes
        parent.children.append(child)
    }

    private func flatten(_ root: Node) -> [ComponentEntry] {
        var rows: [ComponentEntry] = []
        func emit(_ node: Node) {
            rows.append(ComponentEntry(
                path: node.path, name: node.name, kind: node.kind, parent: node.parent,
                regularFileCount: node.regularFiles, symbolicLinkCount: node.symbolicLinks,
                totalBytes: node.totalBytes, unreadableItems: node.unreadable))
            for child in node.children { emit(child) }
        }
        emit(root)
        return rows
    }

    // MARK: Classification

    private func packagedKind(for name: String) -> ArtifactKind? {
        switch name.split(separator: ".", omittingEmptySubsequences: false).last.map(String.init)?.lowercased() ?? "" {
        case "app": .application
        case "framework": .framework
        case "bundle": .bundle
        case "xpc": .xpcService
        case "plugin": .plugin
        case "appex": .appExtension
        case "kext": .kernelExtension
        case "systemextension": .systemExtension
        case "pkg", "mpkg": .package
        case "dmg": .diskImage
        default: nil
        }
    }

    private func fileComponentKind(name: String, values: URLResourceValues,
                                   enclosingDirectoryName: String?) -> ArtifactKind? {
        if let packaged = packagedKind(for: name) { return packaged }
        if let enclosingDirectoryName,
           Self.helperDirectories.contains(enclosingDirectoryName),
           values.isExecutable == true {
            return .helper
        }
        return nil
    }

    // MARK: Helpers

    private func entries(of directory: URL) throws -> [URL] {
        try FileManager.default.contentsOfDirectory(at: directory,
                                                    includingPropertiesForKeys: Array(Self.resourceKeys))
    }

    private func joinPath(_ parent: String, _ component: String) -> String {
        parent.isEmpty ? component : parent + "/" + component
    }

    private func symlinkSize(_ url: URL) -> UInt64 {
        var status = stat()
        // lstat describes the link itself rather than its target.
        return lstat(url.path, &status) == 0 ? UInt64(status.st_size) : 0
    }
}

