import Foundation
import ReleaseLensCore

let usage = """
Usage:
  releaselens scan <artifact-path> [--pretty]
  releaselens components <artifact-path> [--pretty]
"""

let arguments = Array(CommandLine.arguments.dropFirst())

let subcommand = arguments.first
let positional = arguments.dropFirst().filter { $0 != "--pretty" }
let pretty = arguments.dropFirst().contains("--pretty")

guard let subcommand, ["scan", "components"].contains(subcommand),
      positional.count == 1,
      arguments.dropFirst().allSatisfy({ $0 == "--pretty" || $0 == positional.first }) else {
    FileHandle.standardError.write(Data(usage + "\n", utf8))
    exit(64)
}

let path = String(positional[0])

do {
    let encoder = JSONEncoder()
    encoder.outputFormatting = pretty ? [.prettyPrinted, .sortedKeys] : [.sortedKeys]
    let payload: Any
    switch subcommand {
    case "scan":
        payload = try ArtifactScanner().scan(URL(fileURLWithPath: path))
    default:
        payload = try ArtifactScanner().inspectComponents(URL(fileURLWithPath: path))
    }
    FileHandle.standardOutput.write(try encoder.encode(payload as! Encodable))
    FileHandle.standardOutput.write(Data("\n".utf8))
} catch {
    FileHandle.standardError.write(Data("\(error.localizedDescription)\n".utf8))
    exit(1)
}

